const mdxContent = $input.first().json.content[0].text;
const slugMatch = mdxContent.match(/slug:\s*["']([^"']+)["']/);
const slug = slugMatch ? slugMatch[1] : $('Webhook - Generate Blog').first().json.keyword.toLowerCase().replace(/[^a-z0-9]+/g, '-');
const date = new Date().toISOString().split('T')[0];
const fileName = date + '-' + slug + '.mdx';
return [{ json: { mdxContent, slug, fileName } }];

const item = $input.first();
const mdxContent = item.json.mdxContent;
const fileName = item.json.fileName;
const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(mdxContent, 'utf-8'),
  fileName,
  'text/plain'
);
return [{ json: item.json, binary: { data: binaryData } }];
